/** The start and end pictures of a library exercise, or null when it has none. */
export function picturesFor(key: string | null | undefined): ExercisePictures | null {
  if (!key) return null;
  return Object.prototype.hasOwnProperty.call(EXERCISE_PICTURES, key) ? EXERCISE_PICTURES[key] : null;
}
